/* Visual contract only. All values are synthetic; no network calls. */
'use strict';
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',signal:'<path d="M2 13h4l3-8 5 15 3-9 2 2h3"/>',events:'<path d="M12 3 2.5 20h19L12 3Z"/><path d="M12 9v5m0 3v.1"/>',trends:'<path d="M4 3v17h17M7 15l4-5 4 2 5-7"/>',asset:'<rect x="4" y="7" width="16" height="12" rx="2"/><path d="M8 7V4h8v3M8 11v4m4-4v4m4-4v4M2 19h20"/>',network:'<path d="M3 8a14 14 0 0 1 18 0M6 12a9 9 0 0 1 12 0M9 16a4 4 0 0 1 6 0"/><circle cx="12" cy="20" r=".5"/>',voice:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v1a7 7 0 0 0 14 0v-1M12 18v4m-4 0h8"/>',check:'<path d="m5 12 4 4L19 6"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 3"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.overview}</svg>`;
const S={page:'overview',scenario:'normal',signalTab:'spectrum',range:'hour',eventFilter:'pending',ack:false,recovered:false,hasEvent:false,baseline:true,modal:null,wizard:1,confirmed:false,wizardCount:0,playing:false,playPct:0};
let timer=null,toastTimer=null;
const pages=[['overview','总览'],['signal','信号'],['events','事件'],['trends','趋势'],['asset','设备'],['network','连接']];
const badge=(text,type='')=>`<span class="badge ${type}"><i class="dot"></i>${text}</span>`;
function model(){const alarm=S.scenario==='alarm',stale=S.scenario==='stale',idle=S.scenario==='idle';return{alarm,stale,idle,offline:S.scenario==='offline',rms:stale?'0.018':idle?'0.002':alarm?'0.084':'0.018',deviation:stale?'—':!S.baseline?'—':idle?'—':alarm?'11.3':'1.3',title:stale?'数据已过期':idle?'静止 / 振动很弱':!S.baseline?'尚未建立运行基线':alarm?'振动偏离基线':'基线范围内',status:stale?'12 秒前更新':idle?'暂停运行基线判断':!S.baseline?'物理量有效 · 暂不能比较':alarm?'具体故障类型未确定':'低频振动监测 · 0.2 秒前更新'};}
function chart({kind='rms',alarm=false,tall=false,gap=false,range=null}={}){const width=630,height=tall?164:106,left=35,right=614,top=7,bottom=height-20;let pts=[],base=[];for(let i=0;i<90;i++){const x=left+(right-left)*i/89;let y,b;if(kind==='spectrum'){b=.08+.28*Math.exp(-Math.pow((i-21)/8,2))+.12*Math.exp(-Math.pow((i-60)/11,2));y=b+.02*Math.sin(i*.7)+(alarm?.43*Math.exp(-Math.pow((i-45)/4,2)):0);}else if(kind==='wave'){b=.4;y=.42+Math.sin(i*1.3)*.25*(alarm?1.4:1)+Math.cos(i*.23)*.04;}else{b=.29;y=.3+.022*Math.sin(i*.65)+.012*Math.cos(i*.2)+(alarm&&i>58?(i-58)/31*.45:0);}pts.push(`${x.toFixed(1)},${(bottom-y*(bottom-top)).toFixed(1)}`);base.push(`${x.toFixed(1)},${(bottom-b*(bottom-top)).toFixed(1)}`);}let grid='';for(let i=0;i<3;i++){const y=top+(bottom-top)*i/2;grid+=`<line class="gridline" x1="${left}" y1="${y}" x2="${right}" y2="${y}"/><text x="0" y="${y+4}">${kind==='spectrum'?['0.006','0.003','0'][i]:kind==='wave'?['0.1','0','−0.1'][i]:['0.10','0.05','0'][i]}</text>`;}const labels=kind==='spectrum'?['5','10','20','30','40 Hz']:kind==='wave'?['0','0.25','0.5','0.75','1.0 s']:range==='day'?['昨天','−18 h','−12 h','−6 h','现在']:range==='hour'?['−60 min','−45','−30','−15','现在']:['−60 s','−45','−30','−15','现在'];let axis=labels.map((v,i)=>`<text x="${left+(right-left)*i/4}" y="${height-2}" text-anchor="${i===4?'end':'start'}">${v}</text>`).join('');return`<svg class="chart ${tall?'signal-chart':''}" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="${kind==='spectrum'?'当前与基线频谱对比':'合成振动曲线'}">${grid}${kind!=='wave'&&S.baseline?`<polyline class="baseline" points="${base.join(' ')}"/>`:''}<polyline class="signal ${alarm?'red':''}" points="${pts.join(' ')}"/>${gap?`<rect x="265" y="0" width="70" height="${bottom}" fill="#e7ebe4"/><text x="273" y="${bottom/2}">数据缺口</text>`:''}${axis}</svg>`;}
function heading(title,right='',sub=''){return`<div class="page-heading"><div><h2>${title}</h2>${sub?`<p class="sub">${sub}</p>`:''}</div>${right}</div>`;}
function overview(){const m=model();const action=!S.baseline?'<button class="button small" data-action="baseline">建立基线</button>':badge(m.stale?'已过期':m.idle?'静止':m.alarm?'需要处理':'监测中',m.stale||m.idle?'gray':m.alarm?'danger':'');return`<div class="${m.alarm?'alarm-overview':''}">${heading(m.title,action,m.alarm?'':m.status)}${m.alarm?`<div class="banner">${icon('events')}<div><strong>振动异常</strong><small>${S.ack?'已确认 · 仍异常':'待确认 · 类型未确定'}</small></div><button data-action="event">查看事件 ›</button></div>`:''}<div class="overview-grid"><section class="panel reading"><div class="label">振动 RMS · 动态加速度</div><div class="value ${m.stale?'muted-value':''}">${m.rms}<small>g</small></div><div class="reading-foot">${S.baseline?`基线中位数 0.017 g <span style="margin:0 9px;color:#c4cfc5">/</span> 偏离 <b>${m.deviation}</b>`:'未建立基线，暂不判断异常'}</div><div class="micro-wave">${icon('signal')}</div></section><section class="panel status-panel"><dl><div><dt>实际采样率</dt><dd>${m.stale?'—':'208.1 Hz'}</dd></div><div><dt>信号质量</dt><dd>${m.stale?'数据过期':'有效'}</dd></div><div><dt>已知丢样</dt><dd>0 <span class="label">个</span></dd></div><div><dt>运行基线</dt><dd>${S.baseline?'B03 · 匹配':'未建立'}</dd></div></dl></section></div><section class="panel plot-panel"><div class="plot-heading">最近 60 秒 <div class="legend"><span>当前 RMS</span>${S.baseline?'<span class="base">基线</span>':''}</div></div>${chart({alarm:m.alarm})}</section>${!m.alarm?`<div class="timeline-foot"><span>${m.offline?'网络离线 · 本地监测继续，3 条记录待同步':S.hasEvent?'最近事件：振动偏离基线':'当前无待处理事件'}</span><button class="text-link" data-page="${m.offline?'network':'events'}">${m.offline?'同步详情':'事件中心'} →</button></div>`:''}</div>`;}
function signal(){const m=model();let content;if(S.signalTab==='reasons'){content=`<section class="panel signal-panel"><div class="plot-heading">偏离依据 ${badge('观测依据','gray')}</div><div class="insight"><span>向量 RMS <small class="label">${m.rms} / 0.017 g</small></span><b>${m.deviation}</b></div><div class="insight"><span>18–23 Hz 能量</span><b>${!S.baseline?'—':m.alarm?'9.8':'1.1'}</b></div><div class="insight"><span>峰值因子</span><b>${!S.baseline?'—':m.alarm?'7.2':'0.8'}</b></div></section><p class="info-line">${S.baseline?'触发规则：偏离 ≥6，连续3次。故障类型未确定。':'尚无匹配基线，不能计算偏离依据。'}</p>`;}else{content=`<section class="panel signal-panel"><div class="plot-heading">${S.signalTab==='wave'?'X 轴动态加速度 · g':'低频功率谱 · g²/Hz'}<div class="legend"><span>当前</span>${S.signalTab!=='wave'&&S.baseline?'<span class="base">基线 B03</span>':''}</div></div>${chart({kind:S.signalTab,alarm:m.alarm,tall:true})}</section><div class="metric-grid">${[['RMS',m.rms,'g'],['峰值',m.alarm?'0.271':'0.053','g'],['峰值因子',m.alarm?'3.22':'2.94',''],['峰度',m.alarm?'5.8':'3.1','']].map(([l,v,u])=>`<div class="panel metric"><span class="label">${l}</span><strong>${v} <small>${u}</small></strong></div>`).join('')}</div>`;}return`${heading('信号与依据',`<div class="segmented">${[['wave','波形'],['spectrum','频谱'],['reasons','依据']].map(([v,l])=>`<button data-tab="${v}" class="${S.signalTab===v?'active':''}">${l}</button>`).join('')}</div>`)}${content}`;}
function eventRow(title,meta,state,type='',action='event'){return`<button class="event-row" data-action="${action}"><span class="event-icon ${type}">${icon(type==='green'?'check':'events')}</span><div><div class="event-title">${title}</div><div class="event-meta">${meta}</div></div>${badge(state,type==='red'?'danger':type==='green'?'':'warn')}<span class="chevron">›</span></button>`;}
function events(){const active=S.hasEvent&&!S.recovered;return`${heading('事件中心',`<div class="segmented"><button data-filter="pending" class="${S.eventFilter==='pending'?'active':''}">待处理</button><button data-filter="all" class="${S.eventFilter==='all'?'active':''}">全部</button></div>`)}<div class="panel event-list">${S.hasEvent&&(S.eventFilter==='all'||!S.ack||!S.recovered)?eventRow('振动偏离基线','14:32:08 · 电机 01 · E0017',S.recovered?(S.ack?'已归档':'恢复 · 待确认'):S.ack?'确认 · 仍异常':'待确认',active?'red':'green'):''}${S.eventFilter==='all'?eventRow('振动预警','昨天 16:24 · 电机 01 · E0016','已归档','green','old-event')+eventRow('采集连接中断','昨天 09:08 · 电机 01 · E0015','已归档','green','old-event'):(!S.hasEvent||(S.ack&&S.recovered))?'<div style="padding:46px 20px;text-align:center"><div style="color:var(--accent);font-size:24px">当前无待处理事件</div><p class="sub" style="margin-top:14px">切换“振动异常”场景，体验确认与留证。</p></div>':''}</div><div class="notice">确认表示已经收到报警，设备恢复需要由监测结果判断。<br>${model().offline?'网络离线，确认与事件先保存在设备。':'事件状态、处理记录和证据使用同一个事件编号关联。'}</div>`;}
function trends(){return`${heading('振动趋势',`<div class="segmented"><button data-range="hour" class="${S.range==='hour'?'active':''}">1小时</button><button data-range="day" class="${S.range==='day'?'active':''}">24小时</button></div>`)}<section class="panel signal-panel"><div class="plot-heading">RMS · g <div class="legend"><span>当前</span><span class="base">基线</span></div></div>${chart({alarm:S.hasEvent,tall:true,gap:S.range==='day',range:S.range})}<div class="trend-summary"><span>均值<b>0.019 g</b></span><span>峰值<b>${S.hasEvent?'0.084':'0.027'} g</b></span><span>有效率<b>${S.range==='day'?'97.9':'100'}%</b></span></div></section><div class="timeline-foot"><span>样例区间：${S.range==='hour'?'13:40–14:40':'昨天 14:40–今天 14:40'}</span><button class="text-link" data-action="compare">维修前后对比 →</button></div>`;}
function asset(){return`${heading('设备与基线',badge('当前设备'))}<section class="panel asset-card"><div class="machine-symbol">${icon('asset')}</div><div><h3>电机 01</h3><p class="sub">驱动端 · 水平固定安装</p></div>${badge('工况 A','gray')}</section><section class="panel baseline-panel"><div class="baseline-top"><h3>运行基线</h3>${badge(S.baseline?'B03 · 匹配':'未建立',S.baseline?'':'warn')}</div><div class="detail-grid"><div><span class="label">传感器</span><b>板载 IMU</b></div><div><span class="label">采样配置</span><b>208 Hz · ±4 g</b></div><div><span class="label">有效窗口</span><b>${S.baseline?'60 / 60':'—'}</b></div></div><p class="label">${S.baseline?'基线中位数 0.017 g · 安装修订 01':'建立基线后，才能比较当前振动是否发生变化。'}</p></section><div class="action-row"><button class="button" data-action="baseline">${S.baseline?'重新学习基线':'建立运行基线'}</button><button class="button secondary" data-action="profile">设备档案</button><button class="button secondary" data-action="maintenance">维修记录</button></div><p class="info-line">改变安装、设备或工况后，需要匹配对应基线。</p>`;}
function network(){const m=model();return`${heading('连接与同步',badge(m.offline?'待同步 3 条':'全部已同步',m.offline?'warn':''))}<div class="network-grid"><section class="panel network-card"><div class="top"><h3>Wi-Fi</h3>${badge(m.offline?'已断开':'已连接',m.offline?'warn':'')}</div><p>EdgeLab · ${m.offline?'正在重连':'192.168.1.84'}</p><p>链路状态与本地采集独立</p></section><section class="panel network-card"><div class="top"><h3>MQTT 服务</h3>${badge(m.offline?'离线':'在线',m.offline?'warn':'')}</div><p>edgedoctor.local:8883</p><p>${m.offline?'退避重连 · 本地事件已保存':'最近同步：14:40:02（样例）'}</p></section></div><section class="panel sync-panel"><div class="plot-heading">最近事件同步进度</div><div class="sync-steps"><span>● 本地已保存<b>事件 E0017</b></span><i class="line"></i><span class="${m.offline?'pending':''}">${m.offline?'○':'●'} Broker接收<b>${m.offline?'等待联网':'已接收'}</b></span><i class="line"></i><span class="${m.offline?'pending':''}">${m.offline?'○':'●'} 服务端落库<b>${m.offline?'待同步':'已确认持久化'}</b></span></div></section><div class="system-strip"><span>存储 <b>0.76 MiB 可用</b></span><span>时间 <b>未同步</b></span><span>写入错误 <b>0</b></span></div><button class="button secondary small" data-action="test-notify">测试告警交互</button>`;}
function render(){document.querySelector('#navigation').innerHTML=pages.map(([id,title])=>`<button class="nav-item ${S.page===id?'active':''}" data-page="${id}" aria-current="${S.page===id?'page':'false'}">${icon(id)}<span>${title}</span></button>`).join('');const m=model();document.querySelector('#quality-tag').textContent=m.stale?'数据已过期':m.idle?'振动很弱':'采集有效';document.querySelector('#network-tag').innerHTML=icon('network')+(m.offline?'离线':'在线');document.querySelector('#network-tag').classList.toggle('offline',m.offline);document.querySelector('#voice-button').innerHTML=icon('voice');document.querySelector('#page').innerHTML=({overview,signal,events,trends,asset,network}[S.page])();document.querySelectorAll('[data-scenario]').forEach(el=>el.classList.toggle('selected',el.dataset.scenario===S.scenario));}
function showToast(text){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
function drawer(title,body,actions=''){document.querySelector('#modal-root').innerHTML=`<div class="drawer-shade" data-action="close"></div><section class="drawer" role="dialog" aria-modal="true" aria-label="${title}"><div class="drawer-header"><h2>${title}</h2><button class="close" data-action="close" aria-label="关闭详情">×</button></div><div class="drawer-body">${body}</div>${actions?`<div class="drawer-actions">${actions}</div>`:''}</section>`;}
function openEvent(old=false){S.modal=old?'old-event':'event';const recovered=old||S.recovered,acked=old||S.ack;drawer('事件详情',`<div class="event-hero ${recovered?'recovered':''}"><h3>振动偏离基线</h3><p>${recovered?'已恢复':'具体故障类型未确定'} · ${acked?'已确认收到':'待确认'}</p></div><p class="label">电机 01 · ${old?'E0016':'E0017'} · 设计样例</p><div class="panel key-values"><div><span class="label">触发 RMS</span><b>0.084 g</b></div><div><span class="label">基线偏离</span><b>11.3</b></div><div><span class="label">发生时间</span><b>14:32:08</b></div><div><span class="label">故障证据</span><b>完整 · 10.0 s</b></div></div><div class="lifecycle">14:32:08　检测到持续偏离<br>14:32:13　原始片段保存完成<br>${acked?'<b>14:32:20　操作者已确认收到</b><br>':'等待操作者确认<br>'}${recovered?'<b>14:35:10　已恢复至基线范围</b>':'监测继续，恢复尚未发生'}</div><p class="label">${model().offline?'离线 · 本地已保存，等待同步':'服务端已落库（交互样例）'}</p>`,`<button class="button ${acked?'secondary':'danger'}" data-action="ack" ${acked?'disabled':''}>${acked?'已确认':'确认收到'}</button><button class="button secondary" data-action="evidence">${icon('play')}回放证据</button>`);}
function evidence(){S.modal='evidence';S.playing=false;S.playPct=0;drawer('故障证据 · E0017',`${badge('历史片段','gray')}<p class="history-note">当时的原始振动 · 实时监测继续</p><section class="panel plot-panel"><div class="plot-heading">X 轴加速度 · g</div>${chart({kind:'wave',alarm:true,tall:true})}</section><div class="progress"><span id="play-progress" style="width:0%"></span></div><p class="label" id="play-time">0.0 / 10.0 秒 · 208 Hz · 三轴</p><p class="info-line">原基线 B03 · 完整性校验通过（样例）<br>此回放不会触发正式告警或覆盖实时状态。</p>`,`<button class="button" data-action="play" id="play-button">播放片段</button><button class="button secondary" data-action="event">返回事件</button>`);}
function wizard(){S.modal='baseline';let body,actions;const cancel='<button class="button secondary" data-action="close">取消</button>';if(S.wizard===1){body=`<div class="step-label">01 / 04　核对设备与安装</div><h3>为当前工况建立参考</h3><div class="profile-row"><span>设备</span><b>电机 01</b></div><div class="profile-row"><span>安装位置</span><b>驱动端 · 水平固定</b></div><div class="profile-row"><span>运行工况</span><b>工况 A</b></div><div class="profile-row"><span>采集配置</span><b>208 Hz / ±4 g</b></div><p class="wizard-copy">更换安装位置或工况后，原基线不能直接用于比较。</p>`;actions=cancel+'<button class="button" data-action="wizard-next">下一步</button>';}else if(S.wizard===2){body=`<div class="step-label">02 / 04　确认健康运行</div><h3>这段数据将成为比较基准</h3><p class="wizard-copy">请让设备保持健康、稳定的运行状态。采集过程中不要移动开发板或改变安装。</p><label class="check-row"><input type="checkbox" id="healthy-confirm" ${S.confirmed?'checked':''}>我确认设备当前健康运行，安装与工况保持不变。</label><div class="notice">设计原型将60秒采集加速为约5秒，仅演示交互，不学习真实传感器数据。</div>`;actions=cancel+`<button class="button" data-action="wizard-start" ${S.confirmed?'':'disabled'}>开始采集</button>`;}else if(S.wizard===3){body=`<div class="step-label">03 / 04　采集有效窗口</div><h3>保持当前工况</h3><div class="progress-value"><span id="wizard-count">${S.wizardCount}</span><small> / 60 个有效窗口</small></div><div class="progress"><span id="wizard-progress" style="width:${S.wizardCount/60*100}%"></span></div><p class="wizard-copy">采集有效 · 稳定性检查中<br>演示流程已加速，实际运行需60秒有效数据。</p>`;actions=cancel;}else{body=`<div class="step-label">04 / 04　预览并保存</div><div class="wizard-done">✓</div><h3>参考基线已准备好</h3><div class="panel key-values"><div><span class="label">有效窗口</span><b>60 / 60</b></div><div><span class="label">RMS 中位数</span><b>0.017 g</b></div><div><span class="label">稳定性检查</span><b>通过</b></div><div><span class="label">新版本</span><b>B03（样例）</b></div></div><p class="wizard-copy">保存前，原基线保持有效。这里的保存仅修改原型内存。</p>`;actions=cancel+'<button class="button" data-action="wizard-save">保存基线</button>';}drawer('建立运行基线',body,actions);}
function closeModal(){clearInterval(timer);timer=null;S.modal=null;S.playing=false;document.querySelector('#modal-root').innerHTML='';}
const actions={close:closeModal,event:()=>{clearInterval(timer);openEvent();},'old-event':()=>openEvent(true),ack:()=>{S.ack=true;openEvent();render();showToast('已确认收到 · 异常状态仍保持（样例）');},evidence,baseline:()=>{S.wizard=1;S.confirmed=false;S.wizardCount=0;wizard();},'wizard-next':()=>{S.wizard=2;wizard();},'wizard-start':()=>{if(!S.confirmed)return;S.wizard=3;wizard();timer=setInterval(()=>{S.wizardCount++;const count=document.querySelector('#wizard-count'),progress=document.querySelector('#wizard-progress');if(count)count.textContent=S.wizardCount;if(progress)progress.style.width=S.wizardCount/60*100+'%';if(S.wizardCount>=60){clearInterval(timer);S.wizard=4;wizard();}},80);},'wizard-save':()=>{S.baseline=true;if(S.scenario==='baseline')S.scenario='normal';closeModal();render();showToast('运行基线已保存（原型内存样例）');},play:()=>{if(S.playing){clearInterval(timer);S.playing=false;document.querySelector('#play-button').textContent='继续播放';return;}if(S.playPct>=100)S.playPct=0;S.playing=true;document.querySelector('#play-button').textContent='暂停播放';timer=setInterval(()=>{S.playPct++;document.querySelector('#play-progress').style.width=S.playPct+'%';document.querySelector('#play-time').textContent=(S.playPct/10).toFixed(1)+' / 10.0 秒 · 实时监测继续';if(S.playPct>=100){clearInterval(timer);S.playing=false;document.querySelector('#play-button').textContent='重新播放';}},100);},profile:()=>drawer('设备档案','<div class="profile-row"><span>设备名称</span><b>电机 01</b></div><div class="profile-row"><span>传感器</span><b>板载 IMU</b></div><div class="profile-row"><span>安装位置</span><b>驱动端</b></div><div class="profile-row"><span>轴映射</span><b>X / Y / Z</b></div><div class="profile-row"><span>工况</span><b>工况 A（手工选择）</b></div><p class="wizard-copy">现场五分类尚未验证。当前功能为低频振动与基线偏离监测。</p>'),maintenance:()=>drawer('维修记录','<div class="panel" style="padding:16px"><h3>安装复核</h3><p class="sub">昨天 15:00 · 操作者 01</p><p class="wizard-copy">检查固定方式，确认安装方向未变化。工况 A。</p></div><p class="wizard-copy">维修记录不会自动清除报警。前后对比需要相同安装和工况的数据。</p>','<button class="button secondary" data-action="compare">查看前后对比</button>'),compare:()=>drawer('维修前后对比',`${badge('同工况 · 样例')}<p class="wizard-copy">工况 A · 安装修订 01<br>对比前后各30分钟有效运行数据。</p><div class="panel key-values"><div><span class="label">维修前 RMS</span><b>0.029 g</b></div><div><span class="label">维修后 RMS</span><b>0.018 g</b></div><div><span class="label">前 / 后事件</span><b>2 / 0</b></div><div><span class="label">有效数据</span><b>30 / 30 分钟</b></div></div><p class="wizard-copy">这些是观测变化，不代表剩余寿命或维修效果的因果证明。</p>`),'test-notify':()=>drawer('测试通知链路',`<h3>这是一条测试告警</h3><p class="wizard-copy">实施后，测试消息通过独立测试通道发送，手机标题明确标记“测试”。</p><div class="notice">当前为视觉原型。没有MQTT连接，不会发送真实通知。</div>`,'<button class="button" data-action="test-preview">查看通知样式</button>'),'test-preview':()=>drawer('手机通知样式','<div class="panel" style="padding:20px"><p class="label">EdgeDoctor · 测试通知</p><h3 style="margin-top:14px">电机 01：振动偏离基线</h3><p class="wizard-copy">发生于14:32:08 · 需要处理<br>故障类型未确定 · E0017</p><p class="info-line">点开事件详情，查看证据并确认收到。</p></div><p class="wizard-copy">这是通知卡片预览，不代表渠道已接受或手机实际送达。</p>')};
document.addEventListener('click',event=>{const button=event.target.closest('button,[data-action="close"]');if(!button||button.disabled)return;if(button.dataset.page){S.page=button.dataset.page;render();}else if(button.dataset.scenario){closeModal();S.scenario=button.dataset.scenario;S.baseline=S.scenario!=='baseline';if(S.scenario==='alarm'){S.hasEvent=true;S.ack=false;S.recovered=false;}else if(S.hasEvent&&S.scenario==='normal'){S.recovered=true;}render();}else if(button.dataset.tab){S.signalTab=button.dataset.tab;render();}else if(button.dataset.range){S.range=button.dataset.range;render();}else if(button.dataset.filter){S.eventFilter=button.dataset.filter;render();}else if(actions[button.dataset.action])actions[button.dataset.action]();});
document.addEventListener('change',event=>{if(event.target.id==='healthy-confirm'){S.confirmed=event.target.checked;document.querySelector('[data-action="wizard-start"]').disabled=!S.confirmed;}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();});
document.querySelector('#asset-link').onclick=()=>{S.page='asset';render();};document.querySelector('#network-tag').onclick=()=>{S.page='network';render();};document.querySelector('#voice-button').onclick=()=>{const m=model();drawer('语音查询样例',`${badge('只读诊断快照','gray')}<p class="wizard-copy">“当前设备怎么样？”</p><section class="panel" style="padding:18px;margin-top:18px"><p style="font-size:18px;line-height:1.8">电机01${m.stale?'的数据已过期，最后更新在12秒前。':!S.baseline?'尚未建立运行基线。目前可以查看振动值，暂不能判断是否偏离。':m.idle?'当前静止或振动很弱，已暂停运行基线判断。':m.alarm?'振动偏离基线，RMS为0.084g，具体故障类型未确定。':'低频振动在基线范围内，RMS为0.018g。'}</p></section><p class="info-line">设计样例 · 不调用语音服务或麦克风</p>`);};
render();

function fitCanvas(){document.querySelector('.device-wrap').style.zoom=Math.min(1,(window.innerWidth-40)/836);}
window.addEventListener('resize',fitCanvas);fitCanvas();
